from fastapi import FastAPI
from graphene import ObjectType, Int, String, List, Schema, Field
from fastapi_gql import GQL

class User(ObjectType):
    id = Int()
    name = String()

class Post(ObjectType):
    id = Int()
    title = String()
    author = Field(User)

users_data = [
    {'id': 1, 'name': 'Alice'},
    {'id': 2, 'name': 'Bob'}
]

posts_data = [
    {'id': 1, 'title': 'Post 1', 'authorId': 1},
    {'id': 2, 'title': 'Post 2', 'authorId': 2}
]

class Query(ObjectType):
    users = List(User)
    posts = List(Post)

    def resolve_users(self, info):
        return [User(**u) for u in users_data]

    def resolve_posts(self, info):
        result = []
        for p in posts_data:
            author = next(u for u in users_data if u['id'] == p['authorId'])
            result.append(Post(id=p['id'], title=p['title'], author=User(**author)))
        return result

schema = Schema(query=Query)
app = FastAPI()
GQL(app, schema=schema)

