from fastapi import FastAPI
from graphene import ObjectType, Int, String, List, Schema, Field, Mutation, Argument
from fastapi_gql import GQL

users_data = [{'id': 1, 'name': 'Alice'}, {'id': 2, 'name': 'Bob'}]
posts_data = [
    {'id': 1, 'title': 'Post 1', 'authorId': 1},
    {'id': 2, 'title': 'Post 2', 'authorId': 2},
    {'id': 3, 'title': 'Post 3', 'authorId': 1}
]
next_id = 3

class Post(ObjectType):
    id = Int()
    title = String()
    author = Field(lambda: User)

class User(ObjectType):
    id = Int()
    name = String()
    posts = List(Post)

class CreateUser(Mutation):
    class Arguments:
        name = String(required=True)
    Output = User

    def mutate(self, info, name):
        global next_id
        user = {'id': next_id, 'name': name}
        users_data.append(user)
        next_id += 1
        return User(id=user['id'], name=user['name'])

class Query(ObjectType):
    users = List(User)
    user = Field(User, id=Int(required=True))
    posts = List(Post)

    def resolve_users(self, info):
        result = []
        for u in users_data:
            user_posts = [Post(id=p['id'], title=p['title']) for p in posts_data if p['authorId'] == u['id']]
            result.append(User(id=u['id'], name=u['name'], posts=user_posts))
        return result

    def resolve_user(self, info, id):
        u = next((u for u in users_data if u['id'] == id), None)
        if not u:
            return None
        user_posts = [Post(id=p['id'], title=p['title']) for p in posts_data if p['authorId'] == u['id']]
        return User(id=u['id'], name=u['name'], posts=user_posts)

    def resolve_posts(self, info):
        result = []
        for p in posts_data:
            author = next(u for u in users_data if u['id'] == p['authorId'])
            result.append(Post(id=p['id'], title=p['title'], author=User(id=author['id'], name=author['name'])))
        return result

schema = Schema(query=Query, mutation=CreateUser)
app = FastAPI()
GQL(app, schema=schema)

